    // DP
    const dp0 = Array(n + 1).fill(1); // dp0[u]: ways when u is not matched
    const dp1 = Array(n + 1).fill(0); // dp1[u]: ways when u is matched

    for (const u of postOrder) {
        let prod = 1;
        for (const v of children[u]) {
            prod = (prod * ((dp0[v] + dp1[v]) % MOD)) % MOD;
        }
        dp0[u] = prod;

        let sum = 0;
        for (const v of children[u]) {
