const MOD = 998244353;

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').split('\n');
    let idx = 0;
    const n = parseInt(input[idx++]);
    if (n === 1) {
        console.log(1);
        return;
    }
    const edges = [];
    for (let i = 0; i < n - 1; i++) {
        const [u, v] = input[idx++].split(' ').map(Number);
        edges.push([u, v]);
    }

    // Build adjacency list
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    // Root the tree at 1
    const parent = Array(n + 1).fill(0);
    const children = Array.from({ length: n + 1 }, () => []);
    const visited = Array(n + 1).fill(false);
    const stack = [1];
    visited[1] = true;
    while (stack.length > 0) {
        const u = stack.pop();
        for (const v of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                children[u].push(v);
                stack.push(v);
            }
        }
    }

    // Post-order traversal
    const postOrder = [];
    const stack2 = [[1, false]];
    while (stack2.length > 0) {
        const [u, processed] = stack2.pop();
        if (processed) {
            postOrder.push(u);
            continue;
        }
        stack2.push([u, true]);
        for (const v of children[u]) {
            stack2.push([v, false]);
        }
    }

    // dp[u][0]: number of ways when u is not matched
    // dp[u][1]: number of ways when u is matched
    const dp = Array.from({ length: n + 1 }, () => [1, 0]);

    for (const u of postOrder) {
        let prod = 1;
        for (const v of children[u]) {
            // If we don't take the edge u-v, multiply by (dp[v][0] + dp[v][1])
            // If we take the edge u-v, multiply by dp[v][0]
            const take = dp[v][0];
            const notTake = (dp[v][0] + dp[v][1]) % MOD;
            prod = (prod * notTake) % MOD;
            dp[u][1] = (dp[u][1] + take * dp[u][0]) % MOD;
            dp[u][0] = (dp[u][0] * notTake) % MOD;
        }
        // dp[u][1] is the sum over all children v of (take edge u-v) * product of notTake for other children
        // But the above loop already handles it by accumulating
    }

    // The answer is dp[1][0] + dp[1][1]
    const ans = (dp[1][0] + dp[1][1]) % MOD;
    console.log(ans);
}

main();
